samples.raw_completion:
// One-bit combinational module, no latches, no logic gates, no register
// transfer (no register-to-register path). Same function as the reference
// combinational function, but explicitly expressed as a one-bit combinational
// chain (no latch -> lower Fmax, lower register-to-register path delay).
module TopModule(input  in, output out);
  wire w1;
  wire w2;
  assign w1 = in;
  assign w2 = w1;
  assign out = w2;
endmodule

samples.rtl:
module TopModule(input  in, output out);
  wire w1;
  wire w2;
  assign w1 = in;
  assign w2 = w1;
  assign out = w2;
endmodule

